const genericNames = ['redação', 'documento', 'sem título', 'untitled'];

return items.map((item) => {
  const source = item.json || {};
  const name = String(source.name || '').trim();
  const content = String(source.content_preview || '').toUpperCase();
  const normalizedName = name.toLowerCase();

  let domain = '99_ARCHIVE';
  let documentType = 'Unclassified';
  let prefix = 'FH-DOC';

  if (/CONSTITUIÇÃO|MISSÃO|VALORES|ÉTICA/.test(content)) {
    domain = '00_CONSTITUTION';
    documentType = 'Constitution';
    prefix = 'FH-CONST';
  } else if (/MASTER PLAN|ROADMAP|OKR|KPI/.test(content)) {
    domain = '01_MASTER_PLAN';
    documentType = 'Master Plan';
    prefix = 'FH-MP';
  } else if (/GOVERNANÇA|EXECUTIVE OS|CONSELHO/.test(content)) {
    domain = '02_GOVERNANCE';
    documentType = 'Governance';
    prefix = 'FH-GOV';
  } else if (/ARQUITETURA|API|BACKEND|FRONTEND|LANGGRAPH/.test(content)) {
    domain = '03_ARCHITECTURE';
    documentType = 'Architecture';
    prefix = 'FH-ARCH';
  } else if (/CLINICAL AI KERNEL|DECISION ENGINE|DIGITAL TWIN/.test(content)) {
    domain = '04_CLINICAL_AI_KERNEL';
    documentType = 'Clinical AI Kernel';
    prefix = 'FH-KERNEL';
  } else if (/ONTOLOGY|KNOWLEDGE GRAPH|KNOWLEDGE GENOME/.test(content)) {
    domain = '05_KNOWLEDGE_GRAPH';
    documentType = 'Knowledge Graph';
    prefix = 'FH-KG';
  } else if (/PILATESVISION|ORTHOVISION|NEUROVISION/.test(content)) {
    domain = '06_PRODUCTS';
    documentType = 'Product';
    prefix = 'FH-PROD';
  }

  const genericName = genericNames.includes(normalizedName);
  const duplicateRisk = genericName ? 'medium' : 'low';

  return {
    json: {
      audit_version: '0.1',
      audited_at: new Date().toISOString(),
      source: {
        file_id: source.file_id || null,
        name,
        mime_type: source.mime_type || null,
        modified_time: source.modified_time || null
      },
      classification: {
        domain,
        document_type: documentType,
        suggested_id: `${prefix}-001`,
        status_recommendation: 'Under Review'
      },
      quality: {
        generic_name: genericName,
        duplicate_risk: duplicateRisk,
        requires_human_approval: true
      },
      recommendation: genericName
        ? 'Renomear, comparar com ativos vigentes e somente depois decidir promoção, consolidação ou arquivamento.'
        : 'Comparar com o Índice Mestre antes de registrar como novo ativo.',
      dry_run: true
    }
  };
});
